    reg reset;
    wire shift_ena;

    // Instantiate DUT
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .shift_ena(shift_ena)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer cycle_count;

    initial begin
        clk = 0;
        reset = 0;
        cycle_count = 0;

        // Test 1: Reset behavior (Active high synchronous reset)
        // Wait a bit, then assert reset
        #3;
        reset = 1;
        @(posedge clk);
        #1;
        // Check cycle 0 of reset assertion
        if (shift_ena !== 1'b1) begin
            $display("ERROR: At reset cycle 0, shift_ena is %b, expected 1'b1", shift_ena);
            errors = errors + 1;
        end

        // Keep reset high for another cycle to test synchronous reset hold
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            $display("ERROR: At reset cycle 1, shift_ena is %b, expected 1'b1", shift_ena);
            errors = errors + 1;
        end

        // Deassert reset and check the exact 4-cycle activation sequence
        // According to spec: "Whenever the FSM is reset, assert shift_ena for 4 cycles, then 0 forever"
        reset = 0;

        // We just came out of reset. Let's trace the exact 4 cycles.
        // Cycle 1 (posedge clk after reset deassertion)
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            $display("ERROR: Post-reset cycle 1, shift_ena is %b, expected 1'b1", shift_ena);
            errors = errors + 1;
        end

        // Cycle 2
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            $display("ERROR: Post-reset cycle 2, shift_ena is %b, expected 1'b1", shift_ena);
            errors = errors + 1;
        end

        // Cycle 3
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            $display("ERROR: Post-reset cycle 3, shift_ena is %b, expected 1'b1", shift_ena);
            errors = errors + 1;
        end

        // Cycle 4
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            $display("ERROR: Post-reset cycle 4, shift_ena is %b, expected 1'b1", shift_ena);
            errors = errors + 1;
        end

        // Cycle 5: Should now be 0 forever
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b0) begin
            $display("ERROR: Post-reset cycle 5, shift_ena is %b, expected 1'b0", shift_ena);
            errors = errors + 1;
        end

        // Cycle 6: Should still be 0 forever
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b0) begin
            $display("ERROR: Post-reset cycle 6, shift_ena is %b, expected 1'b0", shift_ena);
            errors = errors + 1;
        end

        // Test 2: Mid-operation reset (asynchronous application, synchronous recognition)
        reset = 1;
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            $display("ERROR: Mid-op reset assertion, shift_ena is %b, expected 1'b1", shift_ena);
            errors = errors + 1;
        end

        reset = 0;
        // Verify another full 4-cycle burst
        repeat (4) begin
            @(posedge clk);
            #1;
            if (shift_ena !== 1'b1) begin
                $display("ERROR: Re-trigger burst, shift_ena dropped prematurely: %b", shift_ena);
                errors = errors + 1;
            end
        end

        @(posedge clk);
        #1;
        if (shift_ena !== 1'b0) begin
            $display("ERROR: Re-trigger burst did not terminate: %b", shift_ena);
            errors = errors + 1;
        end

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
